import { ReactNode, useEffect, useLayoutEffect, useRef, useState } from "react"
import { RRule, RRuleSet } from "rrule"
import { toast } from "sonner"

import { EventInfo } from "@/components/event-parts/EventInfo"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuShortcut,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { MoreButton } from "@/components/ui/more-button"

import { useCalEvents } from "@/contexts/CalEventsContext"
import { useCalendars } from "@/contexts/CalendarStateContext"
import { useDeleteEvent } from "@/contexts/DeleteEventContext"
import { useDuplicateEvent } from "@/contexts/DuplicateEventContext"
import { useSync } from "@/contexts/SyncContext"

import { useLastTimedRange } from "@/hooks/useLastTimedRange"
import { getErrorMessage, api } from "@/lib/api"
import { withDates, type CalendarEvent, type ResponseStatus } from "@/lib/cal-events"
import { conferenceForCalendar } from "@/lib/conference"
import {
  addMinutes,
  DEFAULT_DURATION_MINS,
  isAllDay,
  normalizeAllDayRange,
  toAllDay,
  toTimedAtStartOfDay,
} from "@/lib/event-time"
import { getUserResponseStatus, isEventReadonly } from "@/lib/event-utils"
import { recurrenceToRRuleSet, rruleToRecurrence } from "@/lib/rrule-utils"

export const EditEvent = ({
  event,
  onRequestSave,
  children,
}: {
  event: CalendarEvent | null
  onRequestSave: (current: CalendarEvent, original: CalendarEvent) => void
  children?: ReactNode
}) => {
  const { calendars } = useCalendars()
  const { setActiveEventKey } = useCalEvents()
  const { requestSync } = useSync()

  const [dirtyEvent, setDirtyEvent] = useState<CalendarEvent | null>(event)
  const originalEventRef = useRef<CalendarEvent | null>(event)

  const { triggerDelete } = useDeleteEvent()
  const { triggerDuplicate } = useDuplicateEvent()

  // Populate the form before the popover measures it, including when switching events.
  useLayoutEffect(() => {
    if (event) {
      setDirtyEvent(event)
      originalEventRef.current = event
    }
  }, [event?.id])

  // Delete key shortcut: open delete dialog when no field is focused
  useEffect(() => {
    if (!dirtyEvent) return
    if (isEventReadonly(dirtyEvent, calendars)) return

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key !== "Delete" && e.key !== "Backspace") return

      const active = document.activeElement
      if (
        active instanceof HTMLInputElement ||
        active instanceof HTMLTextAreaElement ||
        (active instanceof HTMLElement && active.isContentEditable)
      ) {
        return
      }

      e.preventDefault()
      triggerDelete(dirtyEvent)
    }

    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [dirtyEvent, calendars, triggerDelete])

  // Keep refs so the unmount cleanup always has the latest values
  const dirtyEventRef = useRef<CalendarEvent | null>(null)
  const onRequestSaveRef = useRef(onRequestSave)

  useEffect(() => {
    dirtyEventRef.current = dirtyEvent
  }, [dirtyEvent])

  useEffect(() => {
    onRequestSaveRef.current = onRequestSave
  })

  // Save to caldir only when the popover/sheet closes (component unmounts)
  useEffect(() => {
    return () => {
      const current = dirtyEventRef.current
      const original = originalEventRef.current
      if (!current || !original) return
      if (JSON.stringify(current) === JSON.stringify(original)) return

      onRequestSaveRef.current(current, original)
    }
  }, [])

  // An occurrence's rule lives on its series master, so edit the copy it
  // carries; RecurrenceEditContext applies it to the series on save.
  const handleRecurrenceChange = (rrule: RRule | RRuleSet | null) => {
    if (!dirtyEvent) return
    const next = rruleToRecurrence(rrule, dirtyEvent.start)
    setDirtyEvent(
      dirtyEvent.recurring_event_id
        ? { ...dirtyEvent, master_recurrence: next }
        : { ...dirtyEvent, recurrence: next },
    )
  }

  const handleReminderAdd = (mins: number) => {
    if (!dirtyEvent) return
    if (dirtyEvent.reminders.includes(mins)) return

    setDirtyEvent({ ...dirtyEvent, reminders: [...dirtyEvent.reminders, mins] })
  }

  const handleReminderRemove = (mins: number) => {
    if (!dirtyEvent) return

    setDirtyEvent({ ...dirtyEvent, reminders: dirtyEvent.reminders.filter((m) => m !== mins) })
  }

  const lastTimedRange = useLastTimedRange(
    dirtyEvent?.start ?? null,
    dirtyEvent?.end ?? null,
    event?.id,
  )

  if (!dirtyEvent) return null

  const { summary, description, start, end, location, url, calendar_slug, recurrence } = dirtyEvent
  const all_day = isAllDay(start)

  const effectiveRecurrence = dirtyEvent.recurring_event_id
    ? dirtyEvent.master_recurrence
    : recurrence
  const recurrenceRRule = effectiveRecurrence ? recurrenceToRRuleSet(effectiveRecurrence) : null
  const calendar = calendars.find((c) => c.slug === calendar_slug)

  const userResponseStatus = getUserResponseStatus(dirtyEvent, calendars)
  const isAttendee = userResponseStatus !== null
  const isPendingInvite = userResponseStatus === "needs-action"
  const isReadonly = isEventReadonly(dirtyEvent, calendars)

  const handleRsvp = async (response: ResponseStatus) => {
    if (!dirtyEvent) return

    try {
      await api.events.rsvp(dirtyEvent, response)
      void requestSync()
      setActiveEventKey(null)
    } catch (err) {
      const message = getErrorMessage(err, "Failed to respond to invite")
      toast.error("Failed to respond to invite", { description: message })
      console.error("rsvp failed:", err)
    }
  }

  return (
    <div data-slot="event-form" className="event-form pt-2 pb-2 flex flex-col grow">
      <div className="flex justify-end pb-1">
        {children}

        {!isReadonly && (
          <OverflowMenu
            onDuplicate={() => triggerDuplicate(dirtyEvent)}
            onDelete={() => triggerDelete(dirtyEvent)}
          />
        )}
      </div>

      <EventInfo
        readonly={isReadonly}
        summary={summary}
        onChangeSummary={(newSummary) => {
          setDirtyEvent({ ...dirtyEvent, summary: newSummary })
        }}
        description={description}
        onDescriptionChange={(newDescription) => {
          setDirtyEvent({ ...dirtyEvent, description: newDescription || null })
        }}
        start={start}
        end={end}
        onChangeDateTime={({ start: newStart, end: newEnd }) => {
          setDirtyEvent(withDates(dirtyEvent, newStart, newEnd))
        }}
        allDay={all_day}
        onAllDayChange={(checked) => {
          if (checked) {
            const allDayStart = toAllDay(start)
            const { end: allDayEnd } = normalizeAllDayRange(allDayStart, toAllDay(end))
            setDirtyEvent(withDates(dirtyEvent, allDayStart, allDayEnd))
          } else {
            const timedStart = isAllDay(start) ? toTimedAtStartOfDay(start) : start
            setDirtyEvent(
              withDates(
                dirtyEvent,
                lastTimedRange?.start ?? timedStart,
                lastTimedRange?.end ?? addMinutes(timedStart, DEFAULT_DURATION_MINS),
              ),
            )
          }
        }}
        location={location}
        onLocationChange={(newLocation) => {
          setDirtyEvent({ ...dirtyEvent, location: newLocation || null })
        }}
        url={url}
        onUrlChange={(newUrl) => {
          setDirtyEvent({ ...dirtyEvent, url: newUrl || null })
        }}
        calendar={calendar}
        onCalendarChange={(newCalendarId) => {
          const newCalendar = calendars.find((candidate) => candidate.slug === newCalendarId)
          setDirtyEvent({
            ...dirtyEvent,
            calendar_slug: newCalendarId,
            conference: conferenceForCalendar(dirtyEvent.conference, newCalendar),
          })
        }}
        organizer={dirtyEvent.organizer}
        attendees={dirtyEvent.attendees}
        onAttendeesChange={(newAttendees) => {
          setDirtyEvent({ ...dirtyEvent, attendees: newAttendees })
        }}
        conference={dirtyEvent.conference}
        onConferenceChange={(conference) => {
          setDirtyEvent({ ...dirtyEvent, conference })
        }}
        recurrence={recurrenceRRule}
        onRecurrenceChange={handleRecurrenceChange}
        reminders={dirtyEvent.reminders}
        onReminderAdd={handleReminderAdd}
        onReminderRemove={handleReminderRemove}
        onRsvp={isAttendee ? handleRsvp : undefined}
        userResponseStatus={userResponseStatus}
        isPendingInvite={isPendingInvite}
        onClose={() => setActiveEventKey(null)}
      />
    </div>
  )
}

const OverflowMenu = ({
  onDuplicate,
  onDelete,
}: {
  onDuplicate: () => void
  onDelete: () => void
}) => {
  return (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger asChild>
        <MoreButton />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuItem onClick={onDuplicate}>
          Duplicate event
          <DropdownMenuShortcut>D</DropdownMenuShortcut>
        </DropdownMenuItem>
        <DropdownMenuItem variant="destructive" onClick={onDelete}>
          Delete event
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

