import { DragRegion } from "@/components/ui/drag-region"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuShortcut,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { SelectButton } from "@/components/ui/select"
import { ShortcutTooltip } from "@/components/ui/shortcut-tooltip"

import { useCalendarNavigation, useCalendars } from "@/contexts/CalendarStateContext"
import { useSettings } from "@/contexts/SettingsContext"

import { formatGroupName, getGroupOptions } from "@/lib/calendar-groups"
import { CalendarView } from "@/lib/calendar-view"
import { today } from "@/lib/event-time"

import { CheckIcon } from "@/icons/check"

export function MainHeader({
  calendarView,
  onChangeCalendarView,
}: {
  calendarView: CalendarView
  onChangeCalendarView: (view: CalendarView) => void
}) {
  const { navigateToDate } = useCalendarNavigation()

  return (
    <div data-slot="main-toolbar" className="shrink-0 flex gap-2 p-(--layout-padding)">
      <div className="flex gap-2 items-center">
        <ToggleSidebarButton />

        <ShortcutTooltip text="Go to Today" shortcut="t">
          <Button tabIndex={-1} variant="secondary" onClick={() => navigateToDate(today())}>
            Today
          </Button>
        </ShortcutTooltip>

        <SettingsButton />
        <InvitesBadge />
        <SyncStatus />
      </div>

      <DragRegion className="grow h-full" />

      <GroupSwitcher />

      <CalendarViewDropdown
        calendarView={calendarView}
        onChangeCalendarView={onChangeCalendarView}
      />

      <SearchButton />
    </div>
  )
}

const CALENDAR_VIEW_OPTIONS: { view: CalendarView; name: string; shortcut: string }[] = [
  { view: "week", name: "Week", shortcut: "W" },
  { view: "month", name: "Month", shortcut: "M" },
  { view: "board", name: "Board", shortcut: "B" },
]

const CalendarViewDropdown = ({
  calendarView,
  onChangeCalendarView,
}: {
  calendarView: CalendarView
  onChangeCalendarView: (view: CalendarView) => void
}) => {
  const currentView = CALENDAR_VIEW_OPTIONS.find((option) => option.view === calendarView)

  return (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger asChild>
        <SelectButton tabIndex={-1}>{currentView?.name ?? "View"}</SelectButton>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-48">
        {CALENDAR_VIEW_OPTIONS.map((option) => (
          <DropdownMenuItem
            key={option.view}
            onSelect={() => onChangeCalendarView(option.view)}
            className="gap-3"
          >
            <span className="flex size-4 items-center justify-center">
              {calendarView === option.view && <CheckIcon className="size-4" />}
            </span>
            <span>{option.name}</span>
            <DropdownMenuShortcut>{option.shortcut}</DropdownMenuShortcut>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

// Switches the active calendar group (app state).
// Hidden unless there are at least 2 groups to switch between.
const GroupSwitcher = () => {
  const { activeGroup, setActiveGroup } = useCalendars()
  const { groups } = useSettings()

  const options = getGroupOptions(groups)
  if (options.length < 2) return null

  return (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger asChild>
        <SelectButton tabIndex={-1}>{formatGroupName(activeGroup)}</SelectButton>
      </DropdownMenuTrigger>

      <DropdownMenuContent align="end" className="w-48">
        {options.map((name) => (
          <DropdownMenuItem key={name} onSelect={() => setActiveGroup(name)} className="gap-3">
            <span className="flex size-4 items-center justify-center">
              {activeGroup === name && <CheckIcon className="size-4" />}
            </span>

            <span>{formatGroupName(name)}</span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

