 * Replace the calendar date, preserving the wallclock and zone. For all-day
 * events this swaps the date directly.
 */
export function withEventDate(et: EventTime, newDate: Temporal.PlainDate): EventTime {
  switch (et.kind) {
    case "date":
      return allDayDate(newDate)
    case "datetime_zoned":
      return {
        kind: "datetime_zoned",
        value: et.value.with({
          year: newDate.year,
          month: newDate.month,
          day: newDate.day,
        }),
      }
    case "datetime_floating":
      return {
        kind: "datetime_floating",
        value: et.value.with({
          year: newDate.year,
          month: newDate.month,
          day: newDate.day,
        }),
      }
    case "datetime_utc": {
      const z = toViewerZonedDateTime(et).with({
        year: newDate.year,
        month: newDate.month,
        day: newDate.day,
      })
      return { kind: "datetime_utc", value: z.toInstant() }
    }
  }
}

/** Returns the stored zone, or the viewer zone for values without one. */
export function eventTzid(et: EventTime): string {
  return et.kind === "datetime_zoned" ? et.value.timeZoneId : getViewerTzid()
}

/** Changes zone while preserving the displayed wallclock, not the instant. */
export function withEventTimeZone(et: EventTime, tzid: string): EventTime {
  switch (et.kind) {
    case "date":
      return et
    case "datetime_zoned":
      return { kind: "datetime_zoned", value: et.value.toPlainDateTime().toZonedDateTime(tzid) }
    case "datetime_floating":
      return { kind: "datetime_zoned", value: et.value.toZonedDateTime(tzid) }
    case "datetime_utc":
      return {
        kind: "datetime_zoned",
        value: toViewerZonedDateTime(et).toPlainDateTime().toZonedDateTime(tzid),
      }
  }
}

